#include "dither_tuning.hpp"

namespace png2amiga::dither_tuning {

// Empirical mean-PSNR maxima over the 10 example images.
//
// Two layers:
//   1. Palette-aware ordered methods (opt-checker, knoll, yliluoma,
//      yliluoma2) get per-method optimal strength — their dither
//      response is method-dependent, not mode-dependent.
//   2. Everything else uses the per-encoder-context Floyd-Steinberg
//      tuned table below. Generated by per-mode sweeps on
//      scap-lores-5bpp; see commit log for grid details.
//
// Conservative default for unlisted contexts: strength=1.0,
// error_clamp=0.35 — the pre-tuning whole-codebase baseline.
//
// strips entries assume the sliced+strips layered encoder with two-pass
// refinement (commit 9f51baa) — strips rides on top of sliced-driven
// per-line palette evolution.
Defaults defaults_for(const Context& ctx) {
    constexpr Defaults kFallback{1.0f, 0.35f};

    // ---- HAM short-circuit: jump straight to the mode-context table.
    // The per-method switch below was tuned against the indexed ED path
    // (lores d=5, refine=8). HAM has its own pre-dither (ham.cpp's
    // diffuse_raw_buffer + DP beam search) that wants a tight
    // error_clamp (0.04) for the beam to land cleanly on local optima.
    // Letting the per-method switch fire shadows the HAM-specific
    // entries below with the wrong (too-loose) error_clamp, so jump
    // past it.
    if (ctx.mode == amiga::Mode::ham6 || ctx.mode == amiga::Mode::ham8) {
        // Resweep 2026-05-03 against SSIMULACRA2 on (electrichues02 /
        // chuck31 / lovers, 320×200), 0.02 strength granularity around
        // the optimum. The previous PSNR-tuned values were dominated:
        // HAM6 alone 1.0/0.04 → 0.80/0.08 (mean S2 66.93 → 67.17 plateau);
        // HAM6+copper has a sharp peak at 0.82 (+0.12 S2 over 0.80);
        // HAM8 alone has the same 0.82 peak (+0.11 S2 over 0.80);
        // HAM8+copper is flat across the entire range — keep 0.70.
        if (ctx.mode == amiga::Mode::ham6) {
            if (ctx.copper) return Defaults{0.82f, 0.04f};  // mean S2 70.09
            return Defaults{0.80f, 0.08f};                  // mean S2 67.17
        }
        // HAM8.
        if (ctx.copper) return Defaults{0.70f, 0.04f};  // mean S2 85.40 (flat)
        return Defaults{0.82f, 0.10f};                  // mean S2 83.30
    }

    // ---- Block-compressed modes: block-grid Floyd-Steinberg between
    // 4×4 block neighbours. 15-image DIV2K 512² fine sweep 2026-05-18
    // at 0.05 step. Each curve is flat ±0.05 S2 across a ~0.2-wide band
    // around the peak, so the exact pinned value isn't load-bearing —
    // these are best-of-grid:
    //   etc2: peak 0.55 (S2 82.63); flat 0.45-0.65
    //   bc1:  peak 0.40 (S2 83.53); flat 0.30-0.50
    //   bc3:  peak 0.50 (S2 83.14); flat 0.35-0.55
    //   bc7:  peak 0.75 (S2 93.20); flat 0.45-0.85
    // BC2 has no separate sweep — same BC1 RGB path; alpha is 4-bit
    // explicit and unaffected by dither strength. Use the BC1 peak.
    if (ctx.mode == amiga::Mode::etc2) return Defaults{0.55f, 0.35f};
    if (ctx.mode == amiga::Mode::bc1) return Defaults{0.40f, 0.35f};
    if (ctx.mode == amiga::Mode::bc2) return Defaults{0.40f, 0.35f};
    if (ctx.mode == amiga::Mode::bc3) return Defaults{0.50f, 0.35f};
    if (ctx.mode == amiga::Mode::bc7) return Defaults{0.75f, 0.35f};
    // ASTC: per-footprint block-ED strength from a 10-image DIV2K @ 256w
    // sweep vs astcenc -medium (the flat 0.75 inherited from BC7 was
    // mistuned for the coarse-weight-grid footprints). Pattern: small/mid
    // footprints absorb full diffusion (0.75); larger/coarser grids can't
    // soak the cross-block residual cleanly and want progressively less
    // (10x8/10x10/12x12 → 0; 8x5/10x6/12x10 → 0.25; 6x6/10x5 → 0.5).
    if (ctx.mode == amiga::Mode::astc_4x4) return Defaults{0.75f, 0.35f};
    if (ctx.mode == amiga::Mode::astc_5x4) return Defaults{0.75f, 0.35f};
    if (ctx.mode == amiga::Mode::astc_5x5) return Defaults{0.75f, 0.35f};
    if (ctx.mode == amiga::Mode::astc_6x5) return Defaults{0.75f, 0.35f};
    if (ctx.mode == amiga::Mode::astc_6x6) return Defaults{0.50f, 0.35f};
    if (ctx.mode == amiga::Mode::astc_8x5) return Defaults{0.25f, 0.35f};
    if (ctx.mode == amiga::Mode::astc_8x6) return Defaults{0.75f, 0.35f};
    if (ctx.mode == amiga::Mode::astc_8x8) return Defaults{0.75f, 0.35f};
    if (ctx.mode == amiga::Mode::astc_10x5) return Defaults{0.50f, 0.35f};
    if (ctx.mode == amiga::Mode::astc_10x6) return Defaults{0.25f, 0.35f};
    if (ctx.mode == amiga::Mode::astc_10x8) return Defaults{0.00f, 0.35f};
    if (ctx.mode == amiga::Mode::astc_10x10) return Defaults{0.00f, 0.35f};
    if (ctx.mode == amiga::Mode::astc_12x10) return Defaults{0.25f, 0.35f};
    if (ctx.mode == amiga::Mode::astc_12x12) return Defaults{0.00f, 0.35f};

    // ---- Palette-aware ordered methods: per-(method, mode, depth)
    // optimal strength against SSIMULACRA2.
    //
    // Resweep 2026-05-08 against SSIMULACRA2 on (electrichues02 /
    // chuck31 / lovers, 320×200 amiga and 640×200 hires), strengths
    // 0.50–1.00 step 0.05–0.10. Pop-search palette work + perf-round
    // OKLab refactors had shifted the optimums materially since the
    // last sweep — palette quality is now high enough that opt-checker
    // collapses pairs to no-checker more readily, so optimal strength
    // varies depth-by-depth (more dither energy at low depth where the
    // palette is sparse, less at high depth where partner-search
    // already finds B==A naturally).
    //
    // error_clamp is unused by these methods but kept at 0.35 for CLI
    // surface consistency.
    // Mode-buckets shared across the per-method tables below.
    const bool is_lores = (ctx.mode == amiga::Mode::lores ||
                           ctx.mode == amiga::Mode::lores_interlace);
    const bool is_hires = (ctx.mode == amiga::Mode::hires ||
                           ctx.mode == amiga::Mode::hires_interlace);
    switch (ctx.method) {
    case dither::Method::opt_checker:
        // c64 hires/afli (2 colors per cell) prefer less dither.
        if (ctx.mode == amiga::Mode::c64_hires || ctx.mode == amiga::Mode::c64_afli) {
            return Defaults{0.60f, 0.35f};
        }
        if (ctx.mode == amiga::Mode::ehb) return Defaults{0.80f, 0.35f};  // S2 56.69
        if (is_lores) switch (ctx.depth) {
            case 2:
                return Defaults{1.00f, 0.35f};  // S2 -41.78
            case 3:
                return Defaults{1.00f, 0.35f};  // S2   4.76
            case 4:
                return Defaults{0.80f, 0.35f};  // S2  30.43
            case 5:
                return Defaults{0.70f, 0.35f};  // S2  51.87
            default:
                break;
            }
        if (is_hires) switch (ctx.depth) {
            case 2:
                return Defaults{1.00f, 0.35f};  // S2 -45.66
            case 3:
                return Defaults{0.90f, 0.35f};  // S2  -5.19
            case 4:
                return Defaults{0.80f, 0.35f};  // S2  21.59
            default:
                break;
            }
        return Defaults{0.85f, 0.35f};  // fallback for unswept modes
    case dither::Method::opt_line:
        if (ctx.mode == amiga::Mode::ehb) return Defaults{0.80f, 0.35f};  // S2 55.65
        if (is_lores) switch (ctx.depth) {
            case 2:
                return Defaults{0.95f, 0.35f};
            case 3:
                return Defaults{1.00f, 0.35f};
            case 4:
                return Defaults{1.00f, 0.35f};
            case 5:
                return Defaults{0.70f, 0.35f};
            default:
                break;
            }
        if (is_hires) switch (ctx.depth) {
            case 2:
                return Defaults{1.00f, 0.35f};
            case 3:
                return Defaults{0.90f, 0.35f};
            case 4:
                return Defaults{0.80f, 0.35f};
            default:
                break;
            }
        return Defaults{0.80f, 0.35f};
    case dither::Method::opt_line_checker:
        // S2-flat at 0.80 across all amiga (mode, depth) combos.
        return Defaults{0.80f, 0.35f};
    case dither::Method::knoll:
        if (ctx.mode == amiga::Mode::ehb) return Defaults{0.70f, 0.35f};  // S2 55.01
        if (is_lores) switch (ctx.depth) {
            case 2:
                return Defaults{0.80f, 0.35f};
            case 3:
                return Defaults{0.60f, 0.35f};
            case 4:
                return Defaults{0.80f, 0.35f};
            case 5:
                return Defaults{0.60f, 0.35f};
            default:
                break;
            }
        if (is_hires) switch (ctx.depth) {
            case 2:
                return Defaults{0.80f, 0.35f};
            case 3:
                return Defaults{0.80f, 0.35f};
            case 4:
                return Defaults{0.80f, 0.35f};
            default:
                break;
            }
        return Defaults{0.75f, 0.35f};
    case dither::Method::tri_tone:
        // S2-flat at 0.80 across all amiga (mode, depth) combos.
        return Defaults{0.80f, 0.35f};
    case dither::Method::yliluoma1:
        // Strongest depth-sensitivity in the family — drops from 0.95
        // at d=2 to 0.50 at d=5+.
        if (ctx.mode == amiga::Mode::ehb) return Defaults{0.50f, 0.35f};  // S2 34.56
        if (is_lores) switch (ctx.depth) {
            case 2:
                return Defaults{0.95f, 0.35f};
            case 3:
                return Defaults{0.60f, 0.35f};
            case 4:
                return Defaults{0.50f, 0.35f};
            case 5:
                return Defaults{0.50f, 0.35f};
            default:
                break;
            }
        if (is_hires) switch (ctx.depth) {
            case 2:
                return Defaults{0.90f, 0.35f};
            case 3:
                return Defaults{0.70f, 0.35f};
            case 4:
                return Defaults{0.50f, 0.35f};
            default:
                break;
            }
        return Defaults{0.50f, 0.35f};
    case dither::Method::yliluoma:
        if (ctx.mode == amiga::Mode::ehb) return Defaults{0.70f, 0.35f};  // S2 48.08
        if (is_lores) switch (ctx.depth) {
            case 2:
                return Defaults{0.85f, 0.35f};
            case 3:
                return Defaults{0.70f, 0.35f};
            case 4:
                return Defaults{0.60f, 0.35f};
            case 5:
                return Defaults{0.60f, 0.35f};
            default:
                break;
            }
        if (is_hires) switch (ctx.depth) {
            case 2:
                return Defaults{0.85f, 0.35f};
            case 3:
                return Defaults{0.70f, 0.35f};
            case 4:
                return Defaults{0.70f, 0.35f};
            default:
                break;
            }
        return Defaults{0.70f, 0.35f};
    case dither::Method::yliluoma2:
        if (ctx.mode == amiga::Mode::ehb) return Defaults{0.60f, 0.35f};  // S2 55.60
        if (is_lores) switch (ctx.depth) {
            case 2:
                return Defaults{0.80f, 0.35f};
            case 3:
                return Defaults{0.60f, 0.35f};
            case 4:
                return Defaults{0.70f, 0.35f};
            case 5:
                return Defaults{0.60f, 0.35f};
            default:
                break;
            }
        if (is_hires) switch (ctx.depth) {
            case 2:
                return Defaults{0.80f, 0.35f};
            case 3:
                return Defaults{0.70f, 0.35f};
            case 4:
                return Defaults{0.70f, 0.35f};
            default:
                break;
            }
        return Defaults{0.65f, 0.35f};
    // Error diffusion + structure-aware methods: fall through to the
    // mode-context tables below — per-mode tuning wins when there's an
    // entry. The per-method defaults are a separate switch at the end
    // of the function, used only when no mode-specific entry matches.
    //
    // HAM6/HAM8 short-circuit BEFORE this switch (see top of function);
    // HAM has its own pre-dither pipeline (ham.cpp's diffuse_raw_buffer
    // → DP beam search) that wants a tight error_clamp (0.04) and is
    // tuned in the HAM block.
    case dither::Method::floyd_steinberg:
    case dither::Method::atkinson:
    case dither::Method::sierra_lite:
    case dither::Method::stucki:
    case dither::Method::jarvis:
    case dither::Method::gilbert:
    case dither::Method::riemersma:
    case dither::Method::structure_fs:
    case dither::Method::contrast_fs:
    case dither::Method::zhoufang:
    case dither::Method::dbs:
        break;
    default:
        break;
    }

    // ---- strips: layered on top of sliced. -----------------------------------
    if (ctx.scap) {
        if (ctx.dpf) return Defaults{0.9f, 0.10f};                       // 8 colors
        if (ctx.mode == amiga::Mode::ehb) return Defaults{0.9f, 0.10f};  // 64 effective
        return kFallback;
    }

    // (HAM6/HAM8 already short-circuited at the top of the function;
    // HAM4/HAM5/HAM7 fall through to the per-method ED fallback below.)

    // ---- sliced (per-line palette evolution, no strips) ----------------------
    if (ctx.copper) {
        if (ctx.mode == amiga::Mode::ehb) return Defaults{0.9f, 0.20f};  // mean 37.83
        if (ctx.mode == amiga::Mode::lores) {
            if (ctx.chipset == amiga::Chipset::aga) {
                switch (ctx.depth) {
                case 4:
                    return Defaults{1.0f, 0.10f};  // mean 33.20
                case 5:
                    return Defaults{1.0f, 0.10f};  // mean 37.19
                case 6:
                    return Defaults{1.0f, 0.06f};  // mean 44.33
                case 8:
                    return Defaults{1.0f, 0.04f};  // mean 48.14
                default:
                    break;
                }
            } else {
                switch (ctx.depth) {
                case 2:
                    return Defaults{1.0f, 0.10f};  // mean 21.76
                case 3:
                    return Defaults{1.0f, 0.20f};  // mean 26.89
                case 4:
                    return Defaults{1.0f, 0.04f};  // mean 30.92
                case 5:
                    return Defaults{1.0f, 0.10f};  // mean 35.61
                default:
                    break;
                }
            }
        }
        if (ctx.mode == amiga::Mode::hires) {
            switch (ctx.depth) {
            case 3:
                return Defaults{1.0f, 0.10f};  // mean 26.48
            case 4:
                return Defaults{1.0f, 0.20f};  // mean 30.68
            default:
                break;
            }
        }
        return kFallback;
    }

    // ---- Standard modes (no copper, no strips) ----------------------------
    //
    // Strengths re-tuned 2026-04-30 against SSIMULACRA2 (mean over
    // electrichues02 / chuck31 / lovers at the mode-natural
    // raster) after the OCS halve formula fix (b030caa) and the
    // legacy-ED sRGB-residual migration (57b8efa). The previous
    // (PSNR-tuned, then SSIMULACRA2-retuned-on-broken-encoder)
    // values had been pushed conservative to dodge an FS runaway
    // that no longer exists; sweep now picks 0.70 cleanly across
    // most buckets. lace variants share their non-lace siblings —
    // the encoded bitplane buffer is identical (lace is purely a
    // CAMG flag), so the same tuning applies.
    // Resweep 2026-05-03 against SSIMULACRA2 at 0.02 strength
    // granularity (electrichues02 / chuck31 / lovers). error_clamp left
    // at the previous PSNR-tuned values for d=2 and d=4 — those weren't
    // re-explored in this pass and are conservative defaults.
    if (ctx.mode == amiga::Mode::ehb) return Defaults{0.74f, 0.35f};  // S2 59.37 (was 0.80)
    if (ctx.mode == amiga::Mode::lores || ctx.mode == amiga::Mode::lores_interlace) {
        switch (ctx.depth) {
        case 1:
            return Defaults{0.90f, 0.35f};  // unswept (1-bit)
        case 2:
            return Defaults{0.76f, 0.10f};  // S2 -33.92 (was 0.70)
        case 3:
            return Defaults{0.72f, 0.35f};  // S2   6.59 (was 0.60)
        case 4:
            return Defaults{0.72f, 0.20f};  // S2  34.51 (was 0.70)
        case 5:
            return Defaults{0.72f, 0.35f};  // S2  56.81 (was 0.70)
        case 6:
            return Defaults{0.78f, 0.35f};  // S2  72.74 (was 0.70, AGA only)
        default:
            break;
        }
    }
    if (ctx.mode == amiga::Mode::hires || ctx.mode == amiga::Mode::hires_interlace) {
        switch (ctx.depth) {
        case 1:
            return Defaults{0.85f, 0.35f};  // unswept (1-bit)
        case 2:
            return Defaults{0.72f, 0.35f};  // S2 -39.05 (was 0.70)
        case 3:
            return Defaults{0.70f, 0.35f};  // S2  -0.07 (was 0.60)
        case 4:
            return Defaults{0.76f, 0.35f};  // S2  33.49 (was 0.70)
        default:
            break;
        }
    }

    // ---- Per-method ED fallback ------------------------------------------
    // Reached only when no mode-context entry matched (unsupported modes,
    // chunky / DOS / SNES / Genesis / etc.). These are the lores-d=5 sweep
    // optima at 0.02 granularity (commit history for details).
    switch (ctx.method) {
    case dither::Method::floyd_steinberg:
        return Defaults{0.76f, 0.35f};  // S2 56.80
    case dither::Method::floyd_steinberg_oklab:
        // 50-image DIV2K sweep, lores + hires, d=2..8 (OCS for d≤5 lores
        // / d≤4 hires, AGA above). Peak strength is 0.80 at every depth;
        // a single global tuning suffices. Mean ΔS2 vs FS at each peak:
        //   lores  d2 +2.17  d3 +1.37  d4 +0.75  d5 +0.42
        //          d6 +0.16  d7 +0.07  d8 +0.02
        //   hires  d2 +1.05  d3 +1.79  d4 +1.02  d5 +0.44
        //          d6 +0.22  d7 +0.12  d8 +0.05
        // fs-oklab wins at every depth; the gap shrinks with depth, which
        // is expected — a 256-color palette can satisfy almost any picker
        // target so the residual transport space matters less. The high-
        // strength robustness margin (S2 at s=1.0 minus S2 at peak) is
        // also consistently smaller for fs-oklab than FS: FS collapses
        // by 5–10 S2 past s=0.90 at low depth, fs-oklab stays within 2–4.
        // ec is a safety net only; the OKLab residual self-bounds.
        return Defaults{0.80f, 0.35f};
    case dither::Method::atkinson:
        return Defaults{0.74f, 0.35f};  // S2 56.53
    case dither::Method::sierra_lite:
        return Defaults{0.76f, 0.35f};  // S2 56.79
    case dither::Method::stucki:
        return Defaults{0.74f, 0.35f};  // S2 56.33
    case dither::Method::jarvis:
        return Defaults{0.83f, 0.35f};  // S2 56.11
    case dither::Method::gilbert:
        return Defaults{0.72f, 0.35f};  // S2 56.16
    case dither::Method::riemersma:
        return Defaults{0.52f, 0.35f};  // S2 48.96
    case dither::Method::structure_fs:
        return Defaults{0.80f, 0.35f};  // legacy
    case dither::Method::contrast_fs:
        return Defaults{1.00f, 0.35f};  // legacy
    case dither::Method::zhoufang:
        return Defaults{0.60f, 0.35f};  // legacy
    default:
        break;
    }

    return kFallback;
}

}  // namespace png2amiga::dither_tuning
